-- SAMPLE EVENTS for the staging site only (Nathan, 24 Nov 2026): fictional venues and shows, so the app can be
-- compared side by side with seat-filler sites. Safe to run again: it deletes and recreates everything with slug 'sample-%'.
-- Never run on production. Photos come from /sample/*.jpg in the app.
-- Needs migration 20261124160000_categories_and_flags.sql first (category names, listed_at). Listing dates and sales
-- are set so every flag banner shows somewhere: New, Selling fast and Last few.
begin;
delete from public.ticket_types where event_id in (select id from public.events where slug like 'sample-%');
delete from public.events where slug like 'sample-%';
delete from public.venues where slug like 'sample-%';




-- Flags: most nights were listed three weeks ago; these four went up yesterday, so they show "New".
update public.events set listed_at = now() - interval '21 days' where slug like 'sample-%';
update public.events set listed_at = now() - interval '1 day'
 where slug in ('sample-brass-bones', 'sample-open-mic-mayhem', 'sample-swan-lake-in-the-round', 'sample-puppet-picnic-family-matinee');

commit;

select title, category, flag from public.event_listings where slug like 'sample-%' order by starts_at;
